with flagged as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval 15 minutes then 1 else 0 end as is_new_burst from device_readings) select id, device_code, reading_ts, temp_c, humidity, pressure, sum(is_new_burst) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as session_id from flagged;
